void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //Pixel Coords
    vec2 uv = fragCoord/iResolution.xy;
    uv.x *= iResolution.x/iResolution.y;
    uv.x -= 0.9;
    uv.y -= 0.5;
    uv *= 2.;
    mat2 posvel = 0.25*mat2(vec2(0,1),vec2(-1,0));
    //Obj A Variables
    vec2 posa = vec2(-1,0);
    vec2 vela = vec2(0,0.1);
    vec2 acca = vec2(0);
    float ma = 0.01;
    float ra = 0.1;
    //Obj B Variables
    vec2 posb = vec2(-0.1,0);
    vec2 velb = vec2(0,6);
    vec2 accb = vec2(0);
    float mb = 100.;
    float rb = 0.1;
    //Obj C Variables
    vec2 posc = vec2(0.1,0);
    vec2 velc = vec2(0,-0.1);
    vec2 accc = vec2(0);
    float mc = 100.;
    float rc = 0.1;
    vec2 bary = (posa*ma+posb*mb+posc*mc)/(ma+mb+mc);
    for (float i = 0.;i < 60. * iTime; i++) {
        acca = -0.05*((normalize(posa-posb)/pow(length(posa-posb),2.)*mb)+(normalize(posa-posc)/pow(length(posa-posc),2.)*mc));
        accb = -0.05*((normalize(posb-posa)/pow(length(posb-posa),2.)*ma)+(normalize(posb-posc)/pow(length(posb-posc),2.)*mc));
        accc = -0.05*((normalize(posc-posb)/pow(length(posc-posb),2.)*mc)+(normalize(posc-posa)/pow(length(posc-posa),2.)*ma));
        bary = (posa*ma+posb*mb+posc*mc)/(ma+mb+mc);
        vela += acca/60.;
        velb += accb/60.;
        velc += accc/60.;
        posa += vela/60.;
        posb += velb/60.;
        posc += velc/60.;
        posa -= bary;
        posb -= bary;
        posc -= bary;
        bary -= bary;
                }
    float a = ceil(ra-length(uv-posa));
    float b = ceil(rb-length(uv-posb));
    float c = ceil(rc-length(uv-posc));
    // Output to screen
    fragColor = vec4(a,b,c,1.0);
}
